import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure target_state has the right structure
    if target_state.empty:
        target_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])
        target_state = target_state.astype({
            "order_id": "int64",
            "status": "object",
            "amount": "float64",
            "last_seq": "int64"
        })

    # Ensure cdc_events has the right structure
    if cdc_events.empty:
        cdc_events = pd.DataFrame(columns=["seq", "order_id", "op", "status", "amount", "event_ts"])
        cdc_events = cdc_events.astype({
            "seq": "int64",
            "order_id": "int64",
            "op": "object",
            "status": "object",
            "amount": "float64",
            "event_ts": "datetime64[us]"
        })

    # Step 1: Remove duplicate events (same seq) - keep first occurrence
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Step 2: Build a dict of current state indexed by order_id for fast lookup
    state_dict = {}
    for _, row in target_state.iterrows():
        order_id = row["order_id"]
        state_dict[order_id] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"]
        }

    # Step 3: Track which orders had rows (for tombstone detection)
    orders_with_rows = set(target_state["order_id"].unique())

    # Step 4: Process events in seq order (ascending)
    cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    for _, event in cdc_events.iterrows():
        seq = event["seq"]
        order_id = event["order_id"]
        op = event["op"]
        status = event["status"]
        amount = event["amount"]

        # Replay guard: skip if order exists and seq <= last_seq
        if order_id in state_dict:
            if seq <= state_dict[order_id]["last_seq"]:
                continue

        # Apply the operation
        if op in ("I", "U"):
            if order_id not in state_dict:
                # Create new row
                state_dict[order_id] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq
                }
                orders_with_rows.add(order_id)
            else:
                # Update existing row
                state_dict[order_id]["status"] = status
                # For update, NULL amount means keep existing amount
                if pd.notna(amount):
                    state_dict[order_id]["amount"] = amount
                state_dict[order_id]["last_seq"] = seq

        elif op == "D":
            if order_id in state_dict:
                del state_dict[order_id]
            orders_with_rows.add(order_id)

    # Step 5: Build new_state from state_dict
    new_state_rows = []
    for order_id, state in state_dict.items():
        new_state_rows.append({
            "order_id": order_id,
            "status": state["status"],
            "amount": state["amount"],
            "last_seq": state["last_seq"]
        })

    if new_state_rows:
        new_state = pd.DataFrame(new_state_rows)
        new_state = new_state.astype({
            "order_id": "int64",
            "status": "object",
            "amount": "float64",
            "last_seq": "int64"
        })
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])
        new_state = new_state.astype({
            "order_id": "int64",
            "status": "object",
            "amount": "float64",
            "last_seq": "int64"
        })

    # Step 6: Build tombstones - orders whose last applied event was a delete
    tombstone_rows = []

    # For each order that had a row at any point
    for order_id in orders_with_rows:
        # Find the last applied event for this order
        order_events = cdc_events[cdc_events["order_id"] == order_id].sort_values("seq")

        if not order_events.empty:
            last_applied_seq = None
            for _, event in order_events.iterrows():
                seq = event["seq"]
                # Check replay guard
                if order_id in state_dict:
                    if seq <= state_dict[order_id]["last_seq"]:
                        continue
                # Also check if it was replayed (already processed)
                # We need to check the original logic: was this event applied?
                # Reconstruct: if order existed and seq <= last_seq at time of event, skip
                pass

            # Simpler approach: scan events in order, applying replay guard on the fly
            current_last_seq = target_state[target_state["order_id"] == order_id]["last_seq"].values
            current_last_seq = current_last_seq[0] if len(current_last_seq) > 0 else -1

            last_applied_op = None
            last_applied_seq = None

            for _, event in order_events.iterrows():
                seq = event["seq"]
                op = event["op"]

                if seq <= current_last_seq:
                    continue

                last_applied_op = op
                last_applied_seq = seq

                if op in ("I", "U"):
                    current_last_seq = seq
                elif op == "D":
                    current_last_seq = seq

            if last_applied_op == "D":
                tombstone_rows.append({
                    "order_id": order_id,
                    "deleted_seq": last_applied_seq
                })

    if tombstone_rows:
        tombstones = pd.DataFrame(tombstone_rows)
        tombstones = tombstones.astype({
            "order_id": "int64",
            "deleted_seq": "int64"
        })
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])
        tombstones = tombstones.astype({
            "order_id": "int64",
            "deleted_seq": "int64"
        })

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
